// Procedural WebAudio sound engine — no audio files needed.
let ctx = null;
let master = null;
let noiseBuf = null;

function ensure() {
  if (ctx) return;
  ctx = new (window.AudioContext || window.webkitAudioContext)();
  master = ctx.createDynamicsCompressor();
  master.threshold.value = -18;
  master.ratio.value = 8;
  const gain = ctx.createGain();
  gain.gain.value = 0.55;
  master.connect(gain).connect(ctx.destination);

  const len = ctx.sampleRate * 1.5;
  noiseBuf = ctx.createBuffer(1, len, ctx.sampleRate);
  const d = noiseBuf.getChannelData(0);
  for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
}

export function unlockAudio() {
  ensure();
  if (ctx.state === 'suspended') ctx.resume();
}

function noiseSource() {
  const src = ctx.createBufferSource();
  src.buffer = noiseBuf;
  return src;
}

function env(gainNode, t0, attack, peak, decay) {
  const g = gainNode.gain;
  g.setValueAtTime(0.0001, t0);
  g.exponentialRampToValueAtTime(peak, t0 + attack);
  g.exponentialRampToValueAtTime(0.0001, t0 + attack + decay);
}

// Player's own rifle: sharp crack + low thump.
export function playGunshot() {
  ensure();
  const t = ctx.currentTime;

  const crack = noiseSource();
  const cg = ctx.createGain();
  const hp = ctx.createBiquadFilter();
  hp.type = 'highpass';
  hp.frequency.value = 900;
  env(cg, t, 0.002, 0.9, 0.09);
  crack.connect(hp).connect(cg).connect(master);
  crack.start(t); crack.stop(t + 0.15);

  const body = noiseSource();
  const bg = ctx.createGain();
  const lp = ctx.createBiquadFilter();
  lp.type = 'lowpass';
  lp.frequency.setValueAtTime(2200, t);
  lp.frequency.exponentialRampToValueAtTime(180, t + 0.22);
  env(bg, t, 0.004, 0.7, 0.2);
  body.connect(lp).connect(bg).connect(master);
  body.start(t); body.stop(t + 0.3);

  const thump = ctx.createOscillator();
  thump.type = 'sine';
  thump.frequency.setValueAtTime(110, t);
  thump.frequency.exponentialRampToValueAtTime(40, t + 0.12);
  const tg = ctx.createGain();
  env(tg, t, 0.003, 0.5, 0.13);
  thump.connect(tg).connect(master);
  thump.start(t); thump.stop(t + 0.2);
}

// Hostile gunfire — muffled by distance, panned by direction.
export function playEnemyShot(distance, pan = 0) {
  ensure();
  const t = ctx.currentTime;
  const atten = Math.max(0.06, 1 - distance / 45);

  const body = noiseSource();
  const bg = ctx.createGain();
  const lp = ctx.createBiquadFilter();
  lp.type = 'lowpass';
  lp.frequency.value = Math.max(300, 2600 - distance * 70);
  env(bg, t, 0.003, 0.55 * atten, 0.18);
  const p = ctx.createStereoPanner();
  p.pan.value = Math.max(-0.8, Math.min(0.8, pan));
  body.connect(lp).connect(bg).connect(p).connect(master);
  body.start(t); body.stop(t + 0.25);
}

export function playHitmarker() {
  ensure();
  const t = ctx.currentTime;
  const o = ctx.createOscillator();
  o.type = 'square';
  o.frequency.setValueAtTime(2400, t);
  o.frequency.exponentialRampToValueAtTime(1400, t + 0.05);
  const g = ctx.createGain();
  env(g, t, 0.001, 0.12, 0.05);
  o.connect(g).connect(master);
  o.start(t); o.stop(t + 0.07);
}

export function playPlayerHit() {
  ensure();
  const t = ctx.currentTime;
  const o = ctx.createOscillator();
  o.type = 'sine';
  o.frequency.setValueAtTime(180, t);
  o.frequency.exponentialRampToValueAtTime(60, t + 0.18);
  const g = ctx.createGain();
  env(g, t, 0.004, 0.5, 0.2);
  o.connect(g).connect(master);
  o.start(t); o.stop(t + 0.25);

  const n = noiseSource();
  const ng = ctx.createGain();
  const lp = ctx.createBiquadFilter();
  lp.type = 'lowpass';
  lp.frequency.value = 500;
  env(ng, t, 0.002, 0.25, 0.12);
  n.connect(lp).connect(ng).connect(master);
  n.start(t); n.stop(t + 0.18);
}

function click(t, freq, vol) {
  const o = ctx.createOscillator();
  o.type = 'triangle';
  o.frequency.value = freq;
  const g = ctx.createGain();
  env(g, t, 0.001, vol, 0.04);
  o.connect(g).connect(master);
  o.start(t); o.stop(t + 0.06);
}

export function playReload() {
  ensure();
  const t = ctx.currentTime;
  click(t + 0.05, 700, 0.2);          // mag release
  click(t + 0.55, 450, 0.18);         // mag out
  click(t + 1.35, 600, 0.25);         // mag in
  click(t + 1.85, 950, 0.3);          // bolt release
  click(t + 1.89, 500, 0.22);
}

export function playDryFire() {
  ensure();
  click(ctx.currentTime, 1100, 0.18);
}

export function playFootstep(running) {
  ensure();
  const t = ctx.currentTime;
  const n = noiseSource();
  const g = ctx.createGain();
  const lp = ctx.createBiquadFilter();
  lp.type = 'lowpass';
  lp.frequency.value = running ? 700 : 450;
  env(g, t, 0.002, running ? 0.1 : 0.05, 0.07);
  n.connect(lp).connect(g).connect(master);
  n.start(t); n.stop(t + 0.1);
}

export function playRicochet(distance) {
  ensure();
  const t = ctx.currentTime;
  const atten = Math.max(0.05, 1 - distance / 35);
  const o = ctx.createOscillator();
  o.type = 'sawtooth';
  o.frequency.setValueAtTime(3000 + Math.random() * 2000, t);
  o.frequency.exponentialRampToValueAtTime(400, t + 0.08);
  const g = ctx.createGain();
  env(g, t, 0.001, 0.06 * atten, 0.08);
  o.connect(g).connect(master);
  o.start(t); o.stop(t + 0.1);
}
